#include "stdlib/stats/base/dists/negative-binomial/quantile.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/sqrt.h"
#include "stdlib/math/base/special/erfcinv.h"
#include "stdlib/constants/float64/sqrt_two.h"
#include "stdlib/constants/float64/pinf.h"

/**
* Evaluates the quantile function for a negative binomial distribution with number of successes until experiment is stopped `r` and success probability `p` at a probability `k`.
*
* @param k  input value
* @param r  number of successes until experiment is stopped
* @param p  success probability
* @return   evaluated quantile function
*
* @example
* double y = stdlib_base_dists_negative_binomial_quantile( 0.9, 20.0, 0.2 );
* // returns 106.0
*/
double stdlib_base_dists_negative_binomial_quantile( const double k, const double r, const double p ) {
	double q;
	double mu;
	double sigma;
	double sigmaInv;
	double corr;
	double guess;
	double x;
	double x2;
	if (
		stdlib_base_is_nan( k ) ||
		stdlib_base_is_nan( r ) ||
		stdlib_base_is_nan( p ) ||
		r < 0.0 ||
		p < 0.0 ||
		p > 1.0 ||
		k < 0.0 ||
		k > 1.0
	) {
		return 0.0/0.0; // NaN
	}
	if ( k == 0.0 ) {
		return 0.0;
	}
	if ( k == 1.0 ) {
		return HUGE_VAL;
	}
	q = 1.0 - p;
	mu = ( r * q ) / p;
	sigma = sqrt( r * q ) / p;
	sigmaInv = 1.0 / sigma;

	// Cornish-Fisher expansion:
	if ( k < 0.5 ) {
		x = -stdlib_base_erfcinv( 2.0 * k ) * STDLIB_CONSTANT_FLOAT64_SQRT2;
	} else {
		x = stdlib_base_erfcinv( 2.0 * (1.0-k) ) * STDLIB_CONSTANT_FLOAT64_SQRT2;
	}
	x2 = x * x;

	// Skewness correction:
	corr = x + (sigmaInv * ( x2 - 1.0 ) / 6.0);
	guess = round( mu + (sigma * corr) );
	return ( cdf( guess, r, p ) >= k ) ?
		stdlib_base_dists_negative_binomial_search_left( guess, k, r, p ) :
		stdlib_base_dists_negative_binomial_search_right( guess, k, r, p );
}

/**
* Performs a search to the left.
*
* @param x  starting guess
* @param k  probability
* @param r  number of failures until experiment is stopped
* @param p  success probability
* @return   `k` quantile of the specified distribution
*/
double stdlib_base_dists_negative_binomial_search_left( double x, const double k, const double r, const double p ) {
	while ( true ) {
		if ( x == 0 || cdf( x - 1.0, r, p ) < k ) {
			return x;
		}
		x -= 1;
	}
}

/**
* Performs a search to the right.
*
* @param x  starting guess
* @param k  probability
* @param r  number of failures until experiment is stopped
* @param p  success probability
* @return   `k` quantile of the specified distribution
*/
double stdlib_base_dists_negative_binomial_search_right( double x, const double k, const double r, const double p ) {
	while ( true ) {
		x += 1;
		if ( cdf( x, r, p ) >= k ) {
			return x;
		}
	}
}
